    <script>
    (() => {
        if (window.lucide) lucide.createIcons({attrs:{'stroke-width':1.75}});
        const themeButton=document.getElementById('theme-toggle');
        const syncTheme=()=>{const dark=document.documentElement.classList.contains('dark');if(themeButton){themeButton.innerHTML=`<i data-lucide="${dark?'sun':'moon'}" stroke-width="1.75" class="h-4 w-4"></i>`;themeButton.setAttribute('title',dark?'Gunakan tema terang':'Gunakan tema gelap');if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}})}window.dispatchEvent(new CustomEvent('bumcash:theme-change',{detail:{dark}}))};
        themeButton?.addEventListener('click',()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);document.documentElement.classList.toggle('light',!dark);try{localStorage.setItem('bumcash_theme',dark?'dark':'light')}catch(_){}syncTheme()});
        syncTheme();
        const dropdownFallback=()=>{if(window.Alpine)return;document.querySelectorAll('[data-dropdown-trigger]').forEach(trigger=>{const menu=document.getElementById(trigger.dataset.dropdownTrigger);if(!menu)return;menu.removeAttribute('x-cloak');menu.classList.add('hidden');trigger.addEventListener('click',event=>{event.stopPropagation();menu.classList.toggle('hidden');trigger.setAttribute('aria-expanded',String(!menu.classList.contains('hidden')))});document.addEventListener('click',event=>{if(!trigger.parentElement.contains(event.target)){menu.classList.add('hidden');trigger.setAttribute('aria-expanded','false')}})})};document.addEventListener('DOMContentLoaded',dropdownFallback,{once:true});
        const sidebar=document.getElementById('app-sidebar');if(!sidebar)return;const drawer=document.getElementById('mobile-sidebar-drawer');const mobileBackdrop=document.getElementById('mobile-sidebar-backdrop');const key='bumcash_sidebar_collapsed';let desktopSidebarCollapsed=false;let mobileSidebarOpen=false;try{desktopSidebarCollapsed=localStorage.getItem(key)==='true'}catch(_){}document.documentElement.classList.toggle('sidebar-collapsed',desktopSidebarCollapsed);
        const closeMobileSidebar=()=>{mobileSidebarOpen=false;drawer.classList.add('hidden');drawer.setAttribute('aria-hidden','true');document.body.classList.remove('overflow-hidden')};const openMobileSidebar=()=>{if(window.innerWidth>=1024)return;drawer.removeAttribute('x-cloak');mobileSidebarOpen=true;drawer.classList.remove('hidden');drawer.setAttribute('aria-hidden','false');document.body.classList.add('overflow-hidden')};
        document.getElementById('sidebar-toggle')?.addEventListener('click',()=>{desktopSidebarCollapsed=!document.documentElement.classList.contains('sidebar-collapsed');document.documentElement.classList.toggle('sidebar-collapsed',desktopSidebarCollapsed);try{localStorage.setItem(key,String(desktopSidebarCollapsed))}catch(_){}setTimeout(()=>window.dispatchEvent(new Event('resize')),300)});
        document.getElementById('mobile-sidebar-toggle')?.addEventListener('click',openMobileSidebar);document.getElementById('mobile-sidebar-close')?.addEventListener('click',closeMobileSidebar);mobileBackdrop?.addEventListener('click',closeMobileSidebar);document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMobileSidebar()});drawer.querySelectorAll('a,form button').forEach(item=>item.addEventListener('click',closeMobileSidebar));window.addEventListener('resize',()=>{if(window.innerWidth>=1024&&mobileSidebarOpen)closeMobileSidebar()});
    })();
    </script>
